-- =============================================================================
-- DatabaseBackup_ProjectDevHub.sql
-- Full schema + master/lookup seed data export of the ProjectDevHub SQL Server
-- database, generated by querying sys.tables/sys.columns/sys.foreign_keys/
-- sys.indexes/sys.check_constraints/sys.identity_columns/sys.default_constraints
-- directly against the live database (server DESKTOP-TJ7525D\SQLEXPRESS,
-- database ProjectDevHub) — not derived/guessed from the C# model code.
--
-- Table order below follows FK dependency (parent tables before child tables),
-- verified against the real sys.foreign_keys graph.
--
-- Note: while extracting this backup, three master/lookup tables were found to
-- have mojibake-corrupted Thai text (Core.SystemList rows SOLO/TEAM/FLOW,
-- Project.Departments all 4 rows, Project.TechStackCatalog CatalogId=1) caused
-- by an earlier session running an UPDATE/INSERT script through sqlcmd without
-- specifying a UTF-8 codepage. Those values were corrected in the live database
-- (via a parameterized ADO.NET UPDATE, bypassing console codepage entirely)
-- before this export was taken, so the seed data below reflects the corrected,
-- intended text. A full sweep of every nvarchar/nchar column in every table
-- confirmed no other rows were affected.
--
-- ⚠ UTF-8 / Thai Text Safety — ต้องระบุ Codepage ทุกครั้งที่รัน ⚠
-- sqlcmd อ่านไฟล์สคริปต์นี้ด้วย Codepage เริ่มต้นของเครื่อง (ไม่ใช่ UTF-8) เว้นแต่จะสั่งชัดเจนด้วย -f 65001
-- ถ้าลืม Flag นี้ ข้อความไทยทุกจุดใน Seed Data ด้านล่าง (SystemList/Departments/TechStackCatalog/ผู้ดูแลระบบ)
-- จะถูกอ่านผิด Codepage แล้ว Insert เป็นตัวอักษรมั่ว (Mojibake) ทันที — เคยเกิดเหตุการณ์นี้มาแล้ว 2 ครั้ง
-- (รอบแรก: SOLO/TEAM/FLOW/Departments/TechStackCatalog, รอบสอง: แถว PRESENT ที่เพิ่มเข้ามาทีหลัง)
--
-- สคริปต์นี้ออกแบบไว้สำหรับ "สร้างฐานข้อมูลใหม่ทั้งก้อน" เท่านั้น (CREATE TABLE ด้านล่างไม่ได้ Guard ด้วย
-- IF NOT EXISTS) — ถ้าฐานข้อมูล ProjectDevHub มีอยู่แล้วและมี Schema ครบ ให้ DROP DATABASE ProjectDevHub
-- ทิ้งก่อน (หรือใช้ชื่อฐานข้อมูลใหม่) แล้วค่อยรันสคริปต์นี้ ไม่เช่นนั้นจะเจอ Error "There is already an
-- object named ... in the database" ที่ CREATE TABLE ตัวแรกที่ชนกัน
--
-- Restore แบบสร้างฐานข้อมูลใหม่ทั้งก้อน (เชื่อมต่อไปที่ master ก่อน เพราะฐานข้อมูล ProjectDevHub ยังไม่มีอยู่จริง —
-- สคริปต์จะ CREATE DATABASE ให้เองที่บรรทัดถัดไป แล้ว USE เข้าไปสร้าง Schema/Table/Seed Data ต่ออัตโนมัติ):
--   sqlcmd -S "DESKTOP-TJ7525D\SQLEXPRESS" -U sa -P 1234 -C -d master -f 65001 -i DatabaseBackup_ProjectDevHub.sql
--
-- Default Admin สำหรับ Login ครั้งแรกหลัง Restore (Seed ไว้ใน Section 6):
--   EmpId: ADMIN   Password: Admin@123   (แนะนำให้เปลี่ยนรหัสผ่านทันทีหลังใช้งานจริง)
--
-- Section index: 1) Tables  2) Foreign Keys  3) Unique Constraints/Indexes
-- 4) Non-Unique Indexes  5) Check Constraints  6) Master/Lookup Seed Data
-- 7) Views  8) Stored Procedures  9) Triggers (ครบทุก DB Object ที่มีอยู่จริงบน Live DB
-- ณ วันที่ Export — รันสคริปต์นี้ตัวเดียวสร้างฐานข้อมูลใหม่ได้ครบทุกอย่างโดยไม่ต้องพึ่งขั้นตอนอื่น)
-- =============================================================================

IF NOT EXISTS (SELECT 1 FROM sys.databases WHERE name = 'ProjectDevHub')
BEGIN
    CREATE DATABASE ProjectDevHub;
END
GO

USE ProjectDevHub;
GO

IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Core')     EXEC('CREATE SCHEMA Core');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Project')  EXEC('CREATE SCHEMA Project');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Planning') EXEC('CREATE SCHEMA Planning');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Flow')     EXEC('CREATE SCHEMA Flow');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name = 'Testing')  EXEC('CREATE SCHEMA Testing');
GO

-- =============================================================================
-- SECTION 1 — CREATE TABLE (ordered so every FK's parent table already exists)
-- =============================================================================

-- ---------- Core.Users ----------
CREATE TABLE Core.Users (
    UserId              INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    EmpId               VARCHAR(20)  NOT NULL,
    PasswordHash        VARCHAR(255) NOT NULL,
    FullName            NVARCHAR(100) NOT NULL,
    DivisionName        NVARCHAR(100) NULL,
    DepartmentName      NVARCHAR(100) NULL,
    SectionName         NVARCHAR(100) NULL,
    UserLevel           INT NOT NULL DEFAULT ((1)),
    IsSuperAdmin        BIT NOT NULL DEFAULT ((0)),
    IsSuspended         BIT NOT NULL DEFAULT ((0)),
    IsOnline            BIT NOT NULL DEFAULT ((0)),
    CurrentSessionId    VARCHAR(100) NULL,
    ComputerName        VARCHAR(255) NULL,
    IpAddress           VARCHAR(45)  NULL,
    LastLoginDate       DATETIMEOFFSET(7) NULL,
    IsActive            BIT NOT NULL DEFAULT ((1)),
    CreatedDate         DATETIMEOFFSET(7) NOT NULL DEFAULT (sysdatetimeoffset()),
    UpdatedDate         DATETIMEOFFSET(7) NULL
);
GO

-- ---------- Core.SystemList ----------
CREATE TABLE Core.SystemList (
    SystemId     VARCHAR(50) NOT NULL PRIMARY KEY,
    SystemName   NVARCHAR(100) NOT NULL,
    Description  NVARCHAR(255) NULL,
    IsActive     BIT NOT NULL DEFAULT ((1)),
    CreatedDate  DATETIMEOFFSET(7) NOT NULL DEFAULT (sysdatetimeoffset())
);
GO

-- ---------- Core.Permissions ----------
CREATE TABLE Core.Permissions (
    PermissionId  INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    UserId        INT NOT NULL,
