-- =============================================================================
-- SECTION 2 — FOREIGN KEYS (exact names/actions as queried from sys.foreign_keys)
-- =============================================================================

ALTER TABLE Core.Permissions        ADD CONSTRAINT FK_Permissions_System            FOREIGN KEY (SystemId) REFERENCES Core.SystemList(SystemId);
ALTER TABLE Core.Permissions        ADD CONSTRAINT FK_Permissions_Users             FOREIGN KEY (UserId) REFERENCES Core.Users(UserId) ON DELETE CASCADE;

ALTER TABLE Project.Projects        ADD CONSTRAINT FK_Projects_Owner                FOREIGN KEY (ProjectOwnerId) REFERENCES Core.Users(UserId);
ALTER TABLE Project.Projects        ADD CONSTRAINT FK_Projects_Creator              FOREIGN KEY (CreatedBy) REFERENCES Core.Users(UserId);
ALTER TABLE Project.Projects        ADD CONSTRAINT FK_Projects_ProjectType          FOREIGN KEY (ProjectTypeId) REFERENCES Project.ProjectTypes(ProjectTypeId);

ALTER TABLE Project.Milestones      ADD CONSTRAINT FK_Milestones_Project            FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Project.Milestones      ADD CONSTRAINT FK_Milestones_Owner              FOREIGN KEY (OwnerId) REFERENCES Core.Users(UserId);

ALTER TABLE Project.ProjectMembers  ADD CONSTRAINT FK_ProjectMembers_Project        FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
-- Phase 5: Cascade เมื่อลบ User — ProjectMembers เป็นแค่ความสัมพันธ์ "เป็นสมาชิกของ" ไม่ใช่ข้อมูลที่ User เป็นเจ้าของ
ALTER TABLE Project.ProjectMembers  ADD CONSTRAINT FK_ProjectMembers_User           FOREIGN KEY (UserId) REFERENCES Core.Users(UserId) ON DELETE CASCADE;

ALTER TABLE Project.TechStacks      ADD CONSTRAINT FK_TechStacks_Project            FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;

ALTER TABLE Project.TechStackCatalog ADD CONSTRAINT FK_TechStackCatalog_Type        FOREIGN KEY (TypeId) REFERENCES Project.TechStackCatalog(CatalogId);

ALTER TABLE Project.ShowcaseItems   ADD CONSTRAINT FK_ShowcaseItems_Project         FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Project.ShowcaseItems   ADD CONSTRAINT FK_ShowcaseItems_Creator         FOREIGN KEY (CreatedBy) REFERENCES Core.Users(UserId);

ALTER TABLE Testing.TestSuites      ADD CONSTRAINT FK_TestSuites_Project            FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Testing.TestSuites      ADD CONSTRAINT FK_TestSuites_Creator            FOREIGN KEY (CreatedBy) REFERENCES Core.Users(UserId);

ALTER TABLE Flow.FlowDefinitions    ADD CONSTRAINT FK_FlowDefinitions_Project       FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Flow.FlowDefinitions    ADD CONSTRAINT FK_FlowDefinitions_Creator       FOREIGN KEY (CreatedBy) REFERENCES Core.Users(UserId);

ALTER TABLE Project.Tasks           ADD CONSTRAINT FK_Tasks_Project                 FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Project.Tasks           ADD CONSTRAINT FK_Tasks_Milestone               FOREIGN KEY (MilestoneId) REFERENCES Project.Milestones(MilestoneId);
ALTER TABLE Project.Tasks           ADD CONSTRAINT FK_Tasks_Parent                  FOREIGN KEY (ParentTaskId) REFERENCES Project.Tasks(TaskId);
ALTER TABLE Project.Tasks           ADD CONSTRAINT FK_Tasks_Creator                 FOREIGN KEY (CreatedBy) REFERENCES Core.Users(UserId);

ALTER TABLE Flow.FlowSteps          ADD CONSTRAINT FK_FlowSteps_FlowDefinition      FOREIGN KEY (FlowDefinitionId) REFERENCES Flow.FlowDefinitions(FlowDefinitionId) ON DELETE CASCADE;
ALTER TABLE Flow.FlowSteps          ADD CONSTRAINT FK_FlowSteps_Milestone           FOREIGN KEY (MilestoneId) REFERENCES Project.Milestones(MilestoneId);

ALTER TABLE Flow.FlowTechStacks     ADD CONSTRAINT FK_FlowTechStacks_FlowDefinition FOREIGN KEY (FlowDefinitionId) REFERENCES Flow.FlowDefinitions(FlowDefinitionId) ON DELETE CASCADE;
ALTER TABLE Flow.FlowTechStacks     ADD CONSTRAINT FK_FlowTechStacks_TechStack      FOREIGN KEY (TechStackId) REFERENCES Project.TechStacks(TechStackId);

ALTER TABLE Flow.FlowExecutions     ADD CONSTRAINT FK_FlowExecutions_FlowDefinition FOREIGN KEY (FlowDefinitionId) REFERENCES Flow.FlowDefinitions(FlowDefinitionId) ON DELETE CASCADE;
ALTER TABLE Flow.FlowExecutions     ADD CONSTRAINT FK_FlowExecutions_TriggeredBy    FOREIGN KEY (TriggeredBy) REFERENCES Core.Users(UserId);

ALTER TABLE Testing.TestRuns        ADD CONSTRAINT FK_TestRuns_Suite                FOREIGN KEY (TestSuiteId) REFERENCES Testing.TestSuites(TestSuiteId) ON DELETE CASCADE;
ALTER TABLE Testing.TestRuns        ADD CONSTRAINT FK_TestRuns_TriggeredBy          FOREIGN KEY (TriggeredBy) REFERENCES Core.Users(UserId);

ALTER TABLE Project.TaskAssignees   ADD CONSTRAINT FK_TaskAssignees_Task            FOREIGN KEY (TaskId) REFERENCES Project.Tasks(TaskId) ON DELETE CASCADE;
-- Phase 5: Cascade เมื่อลบ User — TaskAssignees เป็นแค่ความสัมพันธ์ "ถูกมอบหมายงาน" ไม่ใช่ข้อมูลที่ User เป็นเจ้าของ
ALTER TABLE Project.TaskAssignees   ADD CONSTRAINT FK_TaskAssignees_User            FOREIGN KEY (UserId) REFERENCES Core.Users(UserId) ON DELETE CASCADE;

ALTER TABLE Project.Comments        ADD CONSTRAINT FK_Comments_Project              FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Project.Comments        ADD CONSTRAINT FK_Comments_Task                 FOREIGN KEY (TaskId) REFERENCES Project.Tasks(TaskId);
ALTER TABLE Project.Comments        ADD CONSTRAINT FK_Comments_User                 FOREIGN KEY (UserId) REFERENCES Core.Users(UserId);

ALTER TABLE Project.Attachments     ADD CONSTRAINT FK_Attachments_Project           FOREIGN KEY (ProjectId) REFERENCES Project.Projects(ProjectId) ON DELETE CASCADE;
ALTER TABLE Project.Attachments     ADD CONSTRAINT FK_Attachments_Task              FOREIGN KEY (TaskId) REFERENCES Project.Tasks(TaskId);
ALTER TABLE Project.Attachments     ADD CONSTRAINT FK_Attachments_Uploader          FOREIGN KEY (UploadedBy) REFERENCES Core.Users(UserId);

